from admissions_records import *
record('berry-college',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None,'recommended':7,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','recommended':90}]},'alternatives':L('Duolingo preferred score 115. The page calls these minimum preferred scores; they are not treated as unconditional rejection thresholds.','Предпочтительный Duolingo 115. Страница называет эти значения minimum preferred scores; они не превращаются в безусловные пороги отказа.'),'waiver':L('A school official can complete the published English Proficiency Waiver for English-speaking schooling; the admissions team must accept the evidence.','Школьный сотрудник может заполнить опубликованное освобождение English Proficiency Waiver для англоязычной школы; приёмная комиссия должна принять документы.')},academic={'satPolicy':'optional','note':L('SAT/ACT are explicitly listed as optional international application materials.','SAT/ACT прямо включены в необязательные материалы международной заявки.')},documents=[L('First-year school transcripts require WES evaluation if not on the US grading scale; passport and certification of finances required.','Школьные документы первокурсника требуют WES, если шкала не американская; нужны паспорт и подтверждение финансов.')],sources=[S('https://www.berry.edu/admission/how-to-apply/international',L('Berry international first-year requirements','Berry: требования иностранных первокурсников'))])], 'Separated preferred language scores from mandatory documents and optional SAT/ACT.', ['Exact IELTS variant/sections, new TOEFL scale and a Fall 2027-labelled policy not established.'])

record('tuskegee-university',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':62}]},'alternatives':L('Published alternatives: Duolingo 85, PTE 40, iTEP 5.0; the page also lists paper TOEFL 500. No modern 1–6 TOEFL threshold is established.','Опубликованные альтернативы: Duolingo 85, PTE 40, iTEP 5,0; также указан бумажный TOEFL 500. Новый порог TOEFL 1–6 не установлен.'),'waiver':L('The stated US-college English-course waiver is a transfer rule, not an automatic waiver for first-year applicants.','Указанное освобождение за английский в колледже США относится к переводу, а не автоматически к первокурсникам.')},academic={'satPolicy':'required','note':L('The international checklist requests SAT or ACT and lists SAT 1000 / ACT 18. It has no intake year; confirm the policy for Fall 2027 rather than silently applying it to that cycle.','Международный список требует SAT либо ACT и указывает SAT 1000 / ACT 18. Год набора не указан; правило Fall 2027 нужно подтвердить, а не переносить автоматически.')},documents=[L('WES/ECE course-by-course and GPA evaluation, translated school records and financial affidavit/bank evidence.','Оценка WES/ECE по предметам и GPA, переведённые школьные документы и финансовая декларация/банковское подтверждение.')],sources=[S('https://www.tuskegee.edu/admissions/criteria-for-international-students.html',L('Tuskegee international admission criteria','Tuskegee: критерии международного поступления'))])], 'Added the actual published IELTS 5.0 alternatives and required-SAT reference while keeping the unknown cycle explicit.', ['Fall 2027 confirmation, IELTS variant/sections, first-year waivers and new TOEFL scale remain unconfirmed.'])

record('university-of-tampa',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':79},{'period':'post2026','min':4}]},'alternatives':L('Duolingo 110; TOEFL Essentials 8.5. The source’s ACT English 40 waiver figure is impossible on the ACT scale and is not used to confirm a waiver; request clarification.','Duolingo 110; TOEFL Essentials 8,5. Указанные источником ACT English 40 для освобождения невозможны в шкале ACT и не используются для подтверждения освобождения; нужно уточнение.'),'waiver':L('IB Diploma or IB English A HL; ELS 112/Tampa Language Center Level 6; I/GCSE English B; four US high-school English courses I–IV at B or above without ESL; listed citizenship. SAT Reading/Writing 530 is also listed for review.','IB Diploma либо IB English A HL; ELS 112/Tampa Language Center Level 6; I/GCSE English B; четыре школьных предмета English I–IV в США с B или выше без ESL; перечисленное гражданство. SAT Reading/Writing 530 также указан для рассмотрения.')},academic={'satPolicy':'optional','note':L('The first-year international checklist explicitly lists SAT/ACT as optional. Do not reuse the separate transfer English waivers.','Список иностранных первокурсников прямо называет SAT/ACT необязательными. Отдельные языковые освобождения для перевода сюда не переносятся.')},documents=[L('Official secondary records, certified English translations, applicable leaving exams, essay and International Student Financial Form.','Официальные школьные документы, заверенные переводы на английский, применимые выпускные экзамены, эссе и International Student Financial Form.')],sources=[S('https://www.ut.edu/apply/international-students',L('UTampa international first-year requirements','UTampa: требования иностранных первокурсников'))])], 'Recorded current two-scale TOEFL and first-year waivers; excluded the impossible ACT-40 waiver threshold from calculations.', ['The ACT English waiver threshold, IELTS variant/sections and Fall 2027-labelled applicability require confirmation.'])
finish()
